if(p.pasta&&!p.drained&&p.progress>=.9){if(!p.sample||state.time-p.sample.time>45)return 'Check a fresh pasta sample. Slight resistance is the target in this model.';if(!p.reserve&&!n.waterAdded)return 'Reserve some starchy cooking water before you drain the pasta.';return 'The sample is ready. Drain the pasta and turn the pot burner off.';}
if(ready&&!n.garlic)return 'Add the minced garlic now and reduce the pan to low while you finish the pasta. Watch for drying.';
if(ready&&n.heat>1)return 'The produce is ready. Lower the pan heat while waiting for the pasta; the pan will cool gradually.';
if(n.moisture<35&&p.reserve>=50)return 'Use a splash of reserved pasta water to loosen the sauce. Watch the consistency rather than adding all of it at once.';
